/**
 * @summary Get dashboard statistics
 */
export const GetDashboardStatsResponse = zod.object({
  "totalPages": zod.number(),
  "publishedPages": zod.number(),
  "totalNews": zod.number(),
  "publishedNews": zod.number(),
  "totalEvents": zod.number(),
  "upcomingEvents": zod.number(),
  "totalProjects": zod.number(),
  "totalSubmissions": zod.number(),
  "totalTeamMembers": zod.number(),
  "totalPartners": zod.number(),
  "recentSubmissions": zod.array(zod.object({
  "id": zod.number(),
  "formId": zod.number(),
  "formName": zod.string().optional(),
  "data": zod.record(zod.string(), zod.unknown()),
  "ipAddress": zod.string().nullish(),
  "createdAt": zod.string()
})).optional()
})


/**
 * @summary Get recent activity
 */
export const GetDashboardActivityResponseItem = zod.object({
  "id": zod.number(),
  "type": zod.string(),
  "title": zod.string(),
  "action": zod.string(),
  "user": zod.string().nullish(),
  "createdAt": zod.string()
})
export const GetDashboardActivityResponse = zod.array(GetDashboardActivityResponseItem)


/**
 * @summary Request a presigned URL for file upload
 */





export const RequestUploadUrlBody = zod.object({
  "name": zod.string().min(1),
  "size": zod.number().min(1),
  "contentType": zod.string().min(1)
})






export const RequestUploadUrlResponse = zod.object({
  "uploadURL": zod.string(),
  "objectPath": zod.string(),
  "metadata": zod.object({
  "name": zod.string().min(1),
  "size": zod.number().min(1),
  "contentType": zod.string().min(1)
}).optional()
})


